def fizzbuzz(n):
    if n % 15 == 0:
        return "FizzBuzz"
    elif n % 3 == 0:
        return "Fizz"
    elif n % 5 == 0:
        return "Buzz"
    else:
        return str(n)

for i in range(1, 6):
    print(fizzbuzz(i))

def is_palindrome(text):
    for i in range(len(text)):
        if text[i] != text[-1 - i]:
            return False
    return True

print(is_palindrome("level"))
print(is_palindrome("abc"))

